#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_SERVICES 8
#define TOKEN_LEN 32
#define ROLE_USER 0x01
#define ROLE_MERCHANT 0x02
#define ROLE_ADMIN 0x04
#define ROLE_PAYMENT_PROCESSOR 0x08

typedef struct {
    uint32_t service_id;
    uint32_t delegated_roles;
    uint32_t original_roles;
    uint64_t issued_at;
    uint64_t expires_at;
    uint8_t  chain_depth;
    uint32_t issuer_roles;
    uint32_t issuer_id;
} auth_token_t;

typedef struct {
    uint32_t service_id;
    uint32_t roles;
    char     service_name[64];
    int      trust_level;  /* 0=untrusted, 1=internal, 2=privileged */
} service_registry_t;

static service_registry_t registry[MAX_SERVICES] = {
    {1, ROLE_ADMIN | ROLE_PAYMENT_PROCESSOR, "core-gateway", 2},
    {2, ROLE_MERCHANT | ROLE_USER, "merchant-api", 1},
    {3, ROLE_USER, "user-frontend", 0},
    {4, ROLE_PAYMENT_PROCESSOR, "payment-engine", 2},
    {5, ROLE_MERCHANT, "merchant-portal", 1},
    {6, ROLE_USER, "mobile-backend", 0},
    {7, ROLE_ADMIN, "admin-console", 2},
    {8, ROLE_USER | ROLE_MERCHANT, "partner-api", 1}
};

/* Compute allowed delegation: a service can delegate roles it possesses,
   but only to services with equal or higher trust level */
static uint32_t compute_delegation_mask(uint32_t issuer_id, uint32_t target_id) {
    service_registry_t *issuer = NULL, *target = NULL;
    for (int i = 0; i < MAX_SERVICES; i++) {
        if (registry[i].service_id == issuer_id) issuer = &registry[i];
        if (registry[i].service_id == target_id) target = &registry[i];
    }
    if (!issuer || !target) return 0;

    /* Trust level check: target must be >= issuer trust */
    if (target->trust_level < issuer->trust_level) {
        /* Restricted delegation: only USER role can be delegated down */
        return issuer->roles & ROLE_USER;
    }
    return issuer->roles;
}

/* Validate a delegation chain token */
static int validate_chain_token(auth_token_t *token, uint32_t required_role) {
    if (token->expires_at < (uint64_t)time(NULL)) return -1;
    if (token->chain_depth > 3) return -1;

    /* Key check: recompute delegation mask from issuer to target */
    uint32_t allowed = compute_delegation_mask(token->issuer_id, token->service_id);

    /* Verify the token's delegated roles don't exceed computed allowed mask */
    if ((token->delegated_roles & ~allowed) != 0) return -1;

    /* Also verify against issuer's actual registered roles */
    service_registry_t *issuer = NULL;
    for (int i = 0; i < MAX_SERVICES; i++) {
        if (registry[i].service_id == token->issuer_id) { issuer = &registry[i]; break; }
    }
    if (!issuer) return -1;
    if ((token->delegated_roles & ~issuer->roles) != 0) return -1;

    /* Check if required role is present in delegated set */
    if ((token->delegated_roles & required_role) == 0) return -1;

    return 0;
}

/* Create a delegated token from service A to service B */
auth_token_t create_delegation_token(uint32_t issuer_id, uint32_t target_id,
                                      uint32_t requested_roles, uint8_t parent_depth) {
    auth_token_t token = {0};
    token.service_id = target_id;
    token.issuer_id = issuer_id;
    token.issued_at = (uint64_t)time(NULL);
    token.expires_at = token.issued_at + 3600;
    token.chain_depth = parent_depth + 1;

    uint32_t mask = compute_delegation_mask(issuer_id, target_id);

    /* Store issuer's roles for later validation */
    service_registry_t *issuer = NULL;
    for (int i = 0; i < MAX_SERVICES; i++) {
        if (registry[i].service_id == issuer_id) { issuer = &registry[i]; break; }
    }
    token.issuer_roles = issuer ? issuer->roles : 0;

    /* Apply delegation mask to requested roles */
    token.delegated_roles = requested_roles & mask;
    token.original_roles = requested_roles;

    return token;
}

/* Process a payment - requires PAYMENT_PROCESSOR role */
int process_payment(auth_token_t *token, double amount, const char *recipient) {
    if (validate_chain_token(token, ROLE_PAYMENT_PROCESSOR) != 0) {
        printf("[DENIED] Payment of $%.2f to %s - insufficient privileges\n", amount, recipient);
        return -1;
    }
    printf("[APPROVED] Payment of $%.2f to %s processed\n", amount, recipient);
    return 0;
}

/* Refund operation - requires ADMIN role */
int process_refund(auth_token_t *token, double amount, const char *txn_id) {
    if (validate_chain_token(token, ROLE_ADMIN) != 0) {
        printf("[DENIED] Refund of $%.2f for txn %s - insufficient privileges\n", amount, txn_id);
        return -1;
    }
    printf("[APPROVED] Refund of $%.2f for txn %s processed\n", amount, txn_id);
    return 0;
}

/* Simulate cross-service delegation chain attack */
int main(void) {
    printf("=== Payment Processing Auth Demo ===\n\n");

    /* Normal flow: core-gateway (id=1) delegates to payment-engine (id=4) */
    auth_token_t t1 = create_delegation_token(1, 4, ROLE_PAYMENT_PROCESSOR, 0);
    printf("Test 1 - Legitimate delegation:\n");
    process_payment(&t1, 100.00, "vendor-abc");

    /* Attack: merchant-api (id=2, trust=1) creates token claiming
       delegation from itself, but manipulates the chain */
    printf("\nTest 2 - Merchant attempts payment processing:\n");
    auth_token_t t2 = create_delegation_token(2, 2, ROLE_PAYMENT_PROCESSOR, 0);
    process_payment(&t2, 5000.00, "attacker-wallet");

    /* Multi-hop attack: merchant-api delegates to partner-api,
       then partner-api re-delegates with escalated context */
    printf("\nTest 3 - Multi-hop delegation attack:\n");
    auth_token_t t3 = create_delegation_token(2, 8, ROLE_MERCHANT | ROLE_USER, 0);

    /* The attacker now modifies the token in transit (simulating
       a confused deputy via the partner-api service) */
    auth_token_t t4 = t3;
    t4.delegated_roles = ROLE_PAYMENT_PROCESSOR | ROLE_ADMIN;
    t4.issuer_roles = ROLE_ADMIN | ROLE_PAYMENT_PROCESSOR; /* forged */
    t4.chain_depth = 1;

    process_payment(&t4, 50000.00, "attacker-wallet");
    process_refund(&t4, 25000.00, "TXN-LEGIT-001");

    return 0;
}
